using preview::Processor;
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void tick(Processor& p,int n,bool bypass=false){juce::AudioBuffer<float>b(2,n);for(int c=0;c<2;++c)for(int i=0;i<n;++i)b.setSample(c,i,.2f);juce::MidiBuffer m;if(bypass)p.processBlockBypassed(b,m);else p.processBlock(b,m);}
void bypass(){for(int mode=0;mode<2;++mode){Processor p;p.set("mode",float(mode));p.set("output",-12);p.prepareToPlay(48000,127);for(int i=0;i<100;++i)tick(p,127);float previous=.2f*std::pow(10.f,-12.f/20);for(bool off:{true,false,true,false}){float maximum=0;int elapsed=0;for(int n:{7,31,113,257}){juce::AudioBuffer<float>b(2,n);for(int c=0;c<2;++c)for(int i=0;i<n;++i)b.setSample(c,i,.2f);juce::MidiBuffer m;if(off)p.processBlockBypassed(b,m);else p.processBlock(b,m);for(int i=0;i<n;++i){float v=b.getSample(0,i);maximum=std::max(maximum,std::abs(v-previous));previous=v;}elapsed+=n;}check(maximum<.003f,"active bypass boundary step exceeds ramp bound");check(std::abs(previous-(off?.2f:.2f*std::pow(10.f,-12.f/20)))<1e-5,"bypass does not reach endpoint");}std::cout<<"active bypass mode "<<mode<<" passed\n";}}
void activeSignal(){for(int mode=0;mode<2;++mode){Processor p,wet;for(auto* q:{&p,&wet}){q->set("mode",float(mode));q->set("learn",1);q->prepareToPlay(48000,257);}std::mt19937 rng(72);std::normal_distribution<float> noise(0,.025f);std::vector<float> history;float ramp=0;double action=0,hardError=0;int block=0;
 auto run=[&](int count,bool off,bool measure){juce::AudioBuffer<float>a(2,count),b(2,count);const auto start=history.size();for(int i=0;i<count;++i){const float v=noise(rng)+float(.06*std::sin(2*juce::MathConstants<double>::pi*3700*(start+i)/48000.));history.push_back(v);for(int c=0;c<2;++c){a.setSample(c,i,v);b.setSample(c,i,v);}}juce::MidiBuffer m;wet.processBlock(b,m);if(off)p.processBlockBypassed(a,m);else p.processBlock(a,m);for(int i=0;i<count;++i){ramp+=juce::jlimit(-1.f/128,1.f/128,(off?1.f:0.f)-ramp);const auto index=start+i;const float dry=mode?history[index]:(index>=2048?history[index-2048]:0);const float processed=b.getSample(0,i),expected=processed+(dry-processed)*ramp;check(std::abs(a.getSample(0,i)-expected)<2e-6,"active tone/noise bypass violates aligned 128-sample ramp");if(measure){action+=std::abs(dry-processed);hardError+=std::abs(expected-(off?dry:processed));}}++block;};
 for(int i=0;i<40;++i)run(257,false,false);for(auto*q:{&p,&wet}){q->set("learn",0);q->set("denoise",.85f);q->set("resonance",.6f);}for(int i=0;i<40;++i)run(257,false,false);
 for(bool off:{true,false,true,false})for(int n:{7,13,31,127,263})run(n,off,true);
 // Reverse before completion too: the new ramp starts at the current blend.
 run(17,true,true);run(11,false,true);run(257,true,true);run(257,false,true);
 check(action>1,"active reduction positive control absent");check(hardError>.01,"hard-switch negative control not distinguishable");std::cout<<"tone/noise bypass mode "<<mode<<" action "<<action<<" hard-switch error "<<hardError<<"\n";
}}
struct GestureListener:juce::AudioProcessorParameter::Listener{int starts=0,ends=0;void parameterValueChanged(int,float)override{}void parameterGestureChanged(int,bool beginning)override{beginning?++starts:++ends;}};
void graph(){check(preview::GraphModel::marker(int(preview::sp::Shape::Notch),1000,6,32000).y==-6,"positive Notch gain marker must be negative magnitude");for(int shape=0;shape<9;++shape){Processor p;p.prepareToPlay(32000,127);p.setRateAndBufferSizeDetails(32000,127);for(int i=0;i<12;++i){p.set("n"+juce::String(i)+"_freq",20);p.set("n"+juce::String(i)+"_gain",-48);}p.set("n0_shape",float(shape));p.set("n0_freq",1000);p.set("n0_gain",6);auto point=preview::GraphModel::marker(shape,1000,6,32000);auto pos=juce::Point<float>(181+std::log(point.x/20)/std::log(1000.f)*410,154+(24-point.y)/72*137);GestureListener listener;auto* freq=p.state.getParameter("n0_freq");auto* gain=p.state.getParameter("n0_gain");freq->addListener(&listener);gain->addListener(&listener);{std::unique_ptr<juce::AudioProcessorEditor> e(p.createEditor());auto event=[&](juce::Point<float> location){return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),location,juce::ModifierKeys::leftButtonModifier,1,0,0,0,0,e.get(),e.get(),juce::Time::getCurrentTime(),pos,juce::Time::getCurrentTime(),1,true);};if(shape==4){juce::Slider* gainSlider=nullptr;for(auto* child:e->getChildren())if(auto* slider=dynamic_cast<juce::Slider*>(child))if(slider->getComponentID()=="n0_gain")gainSlider=slider;check(gainSlider&&gainSlider->getTextFromValue(6).startsWith("-6"),"positive Notch readout must show negative magnitude");check(p.value("n0_gain")==6,"Notch display mutates imported automation");}e->mouseDown(event(pos));if(shape==4){e->mouseDrag(event({550,159}));check(p.value("n0_gain")==0,"Notch upper graph drag must clamp at zero");}e->mouseDrag(event({550,245}));check(p.value("n0_on")==0,"graph implicitly enables a node");check((std::abs(p.value("n0_freq")-1000)>.1f)==preview::GraphModel::frequency(shape),"graph frequency axis mismatch");check((std::abs(p.value("n0_gain")-6)>.1f)==preview::GraphModel::gain(shape),"graph gain axis mismatch");if(shape==0){p.set("n0_shape",8);e->mouseDrag(event({520,230}));check(listener.starts==listener.ends,"shape interruption leaves gesture open");}if(shape==1){for(auto* child:e->getChildren())if(auto* selector=dynamic_cast<juce::ComboBox*>(child))if(selector->getComponentID()=="node")selector->setSelectedId(2,juce::sendNotificationSync);check(listener.starts==listener.ends,"selection interruption leaves gesture open");}}
 check(listener.starts==listener.ends&&listener.starts>0,"destruction leaves gesture open");freq->removeListener(&listener);gain->removeListener(&listener);
 }check(std::abs(preview::GraphModel::effectiveFrequency(20000,32000)-15680)<.1f,"rate-clamped marker");std::cout<<"all nine graph gesture axes passed\n";}
juce::MemoryBlock stateWithCounter(juce::int64 counter,int routing=0){Processor p;juce::MemoryBlock state;p.getStateInformation(state);auto tree=juce::ValueTree::readFromData(state.getData(),state.getSize());juce::MemoryOutputStream profile;profile.writeDouble(48000);profile.writeInt(routing);profile.writeInt(2048);profile.writeInt64(counter);profile.writeInt64(counter);for(int i=0;i<2114;++i)profile.writeDouble(.001);tree.setProperty("profile",juce::var(profile.getMemoryBlock()),nullptr);juce::MemoryBlock result;juce::MemoryOutputStream out(result,false);tree.writeToStream(out);return result;}
void profiles(){for(auto n:{juce::int64(-1),juce::int64(preview::sp::Processor::maxProfileUpdates+1),std::numeric_limits<juce::int64>::max()}){Processor p;auto b=stateWithCounter(n);p.setStateInformation(b.getData(),int(b.getSize()));juce::MemoryBlock saved;p.getStateInformation(saved);auto tree=juce::ValueTree::readFromData(saved.getData(),saved.getSize());check(!tree.hasProperty("profile"),"malformed counter queued for state export");p.prepareToPlay(48000,127);tick(p,127);check(!p.profilePresent.load(),"malformed profile retained");}for(auto n:{juce::int64(0),juce::int64(12),juce::int64(preview::sp::Processor::maxProfileUpdates)}){Processor p;auto b=stateWithCounter(n);p.setStateInformation(b.getData(),int(b.getSize()));juce::MemoryBlock saved;p.getStateInformation(saved);check(juce::ValueTree::readFromData(saved.getData(),saved.getSize()).hasProperty("profile"),"valid counter rejected");}Processor p;auto b=stateWithCounter(12,1);p.setStateInformation(b.getData(),int(b.getSize()));juce::MemoryBlock saved;p.getStateInformation(saved);check(!juce::ValueTree::readFromData(saved.getData(),saved.getSize()).hasProperty("profile"),"mismatched routing profile exported");std::cout<<"profile validation passed\n";}
void semanticState(){
 auto exportTree=[](Processor& p){juce::MemoryBlock bytes;p.getStateInformation(bytes);return juce::ValueTree::readFromData(bytes.getData(),bytes.getSize());};
 auto validate=[](juce::ValueTree tree){auto v=tree.getProperty("profile");if(auto* bytes=v.getBinaryData()){juce::MemoryInputStream in(*bytes,false);in.readDouble();const int basis=in.readInt();int route=0;for(auto child:tree)if(child.getProperty("id").toString()=="routing")route=int(child.getProperty("value"));return route==basis;}return true;};
 Processor p;p.prepareToPlay(48000,127);auto valid=stateWithCounter(25);auto rejected=stateWithCounter(-1);p.setStateInformation(valid.getData(),int(valid.getSize()));tick(p,127);check(p.profilePresent.load(),"valid profile recovery missing");p.set("routing",1);check(!exportTree(p).hasProperty("profile"),"automation exports old basis before callback");tick(p,127);check(!p.profilePresent.load(),"routing keeps incompatible learning");
 p.setStateInformation(valid.getData(),int(valid.getSize()));p.setStateInformation(rejected.getData(),int(rejected.getSize()));check(!exportTree(p).hasProperty("profile"),"old snapshot survives newer invalid restore");tick(p,127);check(!p.profilePresent.load(),"newest invalid restore not applied");
 std::atomic<bool> done{false},coherent{true};std::thread writer([&]{for(int i=0;i<150;++i){auto& b=i%3?valid:rejected;p.setStateInformation(b.getData(),int(b.getSize()));p.set("routing",float(i%2));if(!validate(exportTree(p)))coherent=false;}done=true;});while(!done.load())tick(p,31);writer.join();check(coherent.load(),"concurrent save pairs incompatible profile and parameters");
 p.setStateInformation(valid.getData(),int(valid.getSize()));tick(p,127);check(p.profilePresent.load(),"valid recovery after concurrent restores");p.clearRequested.store(true);check(!exportTree(p).hasProperty("profile"),"pending clear serialized stale profile");tick(p,127);check(!p.profilePresent.load(),"clear lost after concurrent restore");
 // Learn real broadband noise: the current denoiser deliberately preserves
 // a pure tone when no diffuse noise bed is present.
 std::mt19937 rng(841);std::normal_distribution<float> noise(0,.04f);std::vector<float> input(24000);for(auto&v:input)v=noise(rng);
 Processor learned;learned.set("learn",1);learned.prepareToPlay(48000,127);for(int offset=0;offset<int(input.size());){int n=std::min(127,int(input.size())-offset);juce::AudioBuffer<float> block(2,n);for(int c=0;c<2;++c)for(int i=0;i<n;++i)block.setSample(c,i,input[offset+i]);juce::MidiBuffer midi;learned.processBlock(block,midi);offset+=n;}learned.set("learn",0);learned.set("denoise",.8f);juce::MemoryBlock recalled;learned.getStateInformation(recalled);check(exportTree(learned).hasProperty("profile"),"learned noise not persisted");
 Processor a,b,dry,cleared;for(auto*q:{&a,&b,&dry,&cleared}){q->setStateInformation(recalled.getData(),int(recalled.getSize()));q->prepareToPlay(48000,127);}dry.set("denoise",0);cleared.clearRequested.store(true);
 std::vector<float> results[4];Processor*processors[]={&a,&b,&dry,&cleared};for(int which=0;which<4;++which){auto&q=*processors[which];for(int offset=0;offset<int(input.size());){const int n=std::min(which==1?31:127,int(input.size())-offset);juce::AudioBuffer<float> block(2,n);for(int i=0;i<n;++i)for(int c=0;c<2;++c)block.setSample(c,i,input[offset+i]);juce::MidiBuffer m;q.processBlock(block,m);for(int i=0;i<n;++i)results[which].push_back(block.getSample(0,i));offset+=n;}}
 double power[4]={};for(size_t i=0;i<input.size();++i){check(std::abs(results[0][i]-results[1][i])<2e-6,"profile recall changes with block boundaries");if(i>5000)for(int k=0;k<4;++k)power[k]+=results[k][i]*results[k][i];}
 check(a.profilePresent.load()&&b.profilePresent.load()&&!cleared.profilePresent.load(),"recalled/cleared profile state mismatch");check(power[2]>1,"audible recall dry positive control absent");check(power[0]<power[2]*.8,"recalled denoise lacks audible broadband action");check(std::abs(power[3]-power[2])<power[2]*.001,"cleared profile still removes noise");std::cout<<"recall noise power "<<power[0]<<" dry "<<power[2]<<" cleared "<<power[3]<<"\nsemantic restore/clear/routing and deterministic recall passed\n";

}
void routingReset(){for(int mode=0;mode<2;++mode){Processor p;p.set("mode",float(mode));p.prepareToPlay(48000,127);for(int i=0;i<40;++i)tick(p,127);p.set("routing",1);juce::AudioBuffer<float> block(2,4096);for(int c=0;c<2;++c)for(int i=0;i<4096;++i)block.setSample(c,i,.2f);juce::MidiBuffer m;p.processBlock(block,m);check(std::abs(block.getSample(0,0))<1e-6,"routing reset lacks initial fade");check(std::abs(block.getSample(0,4095)-.2f)<1e-5,"routing reset does not recover sustained audio");check(p.getLatencySamples()==(mode?0:2048),"routing changes latency");}std::cout<<"routing reset/refill policy both modes passed\n";}
void differenceMeaning(){for(int mode=0;mode<2;++mode){Processor delta,wet;for(auto*q:{&delta,&wet}){q->set("mode",float(mode));q->set("resonance",.8f);q->prepareToPlay(48000,127);}delta.set("delta",1);delta.set("mix",.25f);delta.set("output",-9);std::vector<float> history;double action=0;for(int step=0;step<80;++step){juce::AudioBuffer<float>a(2,127),b(2,127);size_t start=history.size();for(int i=0;i<127;++i){float v=float(.2*std::sin((start+i)*.5));history.push_back(v);for(int c=0;c<2;++c){a.setSample(c,i,v);b.setSample(c,i,v);}}juce::MidiBuffer m;delta.processBlock(a,m);wet.processBlock(b,m);for(int i=0;i<127;++i){size_t index=start+i;float dry=mode?history[index]:(index>=2048?history[index-2048]:0);if(index>5000)check(std::abs(a.getSample(0,i)-(dry-b.getSample(0,i)))<2e-6,"settled difference includes mix or output trim");action+=std::abs(a.getSample(0,i));}}check(action>1,"difference active positive control missing");}std::cout<<"raw aligned difference at nondefault mix/trim passed\n";}
void malformedAudio(){for(int mode=0;mode<2;++mode){Processor p;p.set("mode",float(mode));p.prepareToPlay(48000,127);for(bool bypass:{false,true,false,true}){for(int n:{7,127,257,4096}){juce::AudioBuffer<float> block(2,n);const float bad[]={std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),-std::numeric_limits<float>::infinity(),std::numeric_limits<float>::max(),-std::numeric_limits<float>::max()};for(int c=0;c<2;++c)for(int i=0;i<n;++i)block.setSample(c,i,bad[i%5]);juce::MidiBuffer m;if(bypass)p.processBlockBypassed(block,m);else p.processBlock(block,m);for(int c=0;c<2;++c)for(int i=0;i<n;++i)check(std::isfinite(block.getSample(c,i))&&std::abs(block.getSample(c,i))<=1000001,"nonfinite or unbounded wrapper dry blend");}}
 for(int i=0;i<50;++i)tick(p,127);juce::AudioBuffer<float> block(2,127);for(int c=0;c<2;++c)for(int i=0;i<127;++i)block.setSample(c,i,.2f);juce::MidiBuffer m;p.processBlock(block,m);for(int c=0;c<2;++c)for(int i=0;i<127;++i)check(std::abs(block.getSample(c,i)-.2f)<1e-4,"malformed audio poisons recovery");}std::cout<<"NaN/Inf/extreme finite active/bypass/recovery both modes passed\n";}
int main(){gillInitialiseTestApplication();
  juce::ScopedJuceInitialiser_GUI gui;try{malformedAudio();bypass();activeSignal();profiles();semanticState();routingReset();differenceMeaning();graph();std::cout<<"SPECTRA_PREVIEW_REPAIRS_PASS\n";}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
